-- 2026_05_attendance_face_location
-- ------------------------------------------------------------------------
ALTER TABLE organizations ADD COLUMN IF NOT EXISTS attendance_verification_enabled BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE organizations ADD COLUMN IF NOT EXISTS office_latitude DOUBLE PRECISION;
ALTER TABLE organizations ADD COLUMN IF NOT EXISTS office_longitude DOUBLE PRECISION;
ALTER TABLE organizations ADD COLUMN IF NOT EXISTS office_radius_m INTEGER;
ALTER TABLE organizations ADD COLUMN IF NOT EXISTS office_address TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS face_descriptor JSONB;
ALTER TABLE users ADD COLUMN IF NOT EXISTS face_enrolled_at TIMESTAMPTZ;
ALTER TABLE time_entries ADD COLUMN IF NOT EXISTS clock_in_lat DOUBLE PRECISION;
ALTER TABLE time_entries ADD COLUMN IF NOT EXISTS clock_in_lng DOUBLE PRECISION;
ALTER TABLE time_entries ADD COLUMN IF NOT EXISTS clock_in_accuracy_m REAL;
ALTER TABLE time_entries ADD COLUMN IF NOT EXISTS clock_in_distance_m INTEGER;
ALTER TABLE time_entries ADD COLUMN IF NOT EXISTS face_verified BOOLEAN;
ALTER TABLE time_entries ADD COLUMN IF NOT EXISTS face_match_score REAL;
DO $$
                BEGIN
                    IF EXISTS (
                        SELECT 1 FROM information_schema.columns
                        WHERE table_name = 'time_entries' AND column_name = 'clock_in_latitude'
                    ) THEN
                        UPDATE time_entries SET clock_in_lat = clock_in_latitude
                            WHERE clock_in_lat IS NULL AND clock_in_latitude IS NOT NULL;
                        ALTER TABLE time_entries DROP COLUMN clock_in_latitude;
                    END IF;
                    IF EXISTS (
                        SELECT 1 FROM information_schema.columns
                        WHERE table_name = 'time_entries' AND column_name = 'clock_in_longitude'
                    ) THEN
                        UPDATE time_entries SET clock_in_lng = clock_in_longitude
                            WHERE clock_in_lng IS NULL AND clock_in_longitude IS NOT NULL;
                        ALTER TABLE time_entries DROP COLUMN clock_in_longitude;
                    END IF;
                    IF EXISTS (
                        SELECT 1 FROM information_schema.columns
                        WHERE table_name = 'time_entries' AND column_name = 'clock_in_accuracy'
                    ) THEN
                        UPDATE time_entries SET clock_in_accuracy_m = clock_in_accuracy
                            WHERE clock_in_accuracy_m IS NULL AND clock_in_accuracy IS NOT NULL;
                        ALTER TABLE time_entries DROP COLUMN clock_in_accuracy;
                    END IF;
                END $$;

